"use strict";(self.webpackChunkmy_site=self.webpackChunkmy_site||[]).push([["4404"],{7819(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/Differential Geometry and Fibre Bundle/1_2","metadata":{"permalink":"/zh/blog/Differential Geometry and Fibre Bundle/1_2","source":"@site/i18n/zh/docusaurus-plugin-content-blog/Differential Geometry and Fibre Bundle/1_2.mdx","title":"\u5FAE\u5206\u51E0\u4F55\u7684\u7EBF\u6027\u4EE3\u6570\u57FA\u7840","description":"\u6211\u4EEC\u5047\u8BBE\u5927\u5BB6\u5BF9\u7EBF\u6027\u4EE3\u6570\u6709\u6BD4\u8F83\u57FA\u672C\u7684\u4E86\u89E3\uFF0C\u6BD4\u5982\u5411\u91CF\u7A7A\u95F4\u7684\u5B9A\u4E49\u3001\u57FA\u7684\u5B9A\u4E49\u7B49\u7B49\u3002\u6709\u4E00\u4E9B\u57FA\u7840\u7EBF\u6027\u4EE3\u6570\u8BFE\u7A0B\u4E0D\u4F1A\u8BB2\u5230\u7684\u5185\u5BB9\uFF0C\u6211\u4F1A\u5728\u8FD9\u91CC\u58F0\u660E\u57FA\u672C\u7684\u5B9A\u4E49\uFF0C\u66F4\u52A0\u8BE6\u7EC6\u7684\u8BA8\u8BBA\u53EF\u4EE5\u53C2\u8003\u300ALinear Algebra Done Right\u300B\uFF0C\u6216\u8005\u4EFB\u610F\u4E00\u672C\u9AD8\u7B49\u4EE3\u6570\u8BFE\u672C\u3002","date":"2026-05-18T00:00:00.000Z","tags":[{"inline":true,"label":"Differential Geometry","permalink":"/zh/blog/tags/differential-geometry"},{"inline":true,"label":"Linear Algebra","permalink":"/zh/blog/tags/linear-algebra"}],"readingTime":6.36,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"\u5FAE\u5206\u51E0\u4F55\u7684\u7EBF\u6027\u4EE3\u6570\u57FA\u7840","date":"2026-05-18T00:00:00.000Z","tags":["Differential Geometry","Linear Algebra"]},"unlisted":false,"nextItem":{"title":"\u62D3\u6251\u57FA\u7840","permalink":"/zh/blog/Differential Geometry and Fibre Bundle/1_1"}},"content":"\u6211\u4EEC\u5047\u8BBE\u5927\u5BB6\u5BF9\u7EBF\u6027\u4EE3\u6570\u6709\u6BD4\u8F83\u57FA\u672C\u7684\u4E86\u89E3\uFF0C\u6BD4\u5982\u5411\u91CF\u7A7A\u95F4\u7684\u5B9A\u4E49\u3001\u57FA\u7684\u5B9A\u4E49\u7B49\u7B49\u3002\u6709\u4E00\u4E9B\u57FA\u7840\u7EBF\u6027\u4EE3\u6570\u8BFE\u7A0B\u4E0D\u4F1A\u8BB2\u5230\u7684\u5185\u5BB9\uFF0C\u6211\u4F1A\u5728\u8FD9\u91CC\u58F0\u660E\u57FA\u672C\u7684\u5B9A\u4E49\uFF0C\u66F4\u52A0\u8BE6\u7EC6\u7684\u8BA8\u8BBA\u53EF\u4EE5\u53C2\u8003\u300ALinear Algebra Done Right\u300B\uFF0C\u6216\u8005\u4EFB\u610F\u4E00\u672C\u9AD8\u7B49\u4EE3\u6570\u8BFE\u672C\u3002\\n\\n\u8BFB\u8005\u53EF\u80FD\u4F1A\u53D1\u73B0\u6709\u4E00\u4E9B\u8BB0\u53F7\u4E60\u60EF\u4E0E\u5176\u4ED6\u9886\u57DF\u4F7F\u7528\u7684\u4E60\u60EF\u4E0D\u540C\uFF0C\u4E8B\u5B9E\u4E0A\u5B83\u4EEC\u901A\u5E38\u6307\u7684\u662F\u540C\u4E00\u79CD\u4E1C\u897F\uFF0C\u4E0D\u5FC5\u4E3A\u6B64\u611F\u5230\u6050\u60E7\u3002\\n\\n## \u5411\u91CF\u7A7A\u95F4\\n\\n\u5728\u7EBF\u6027\u4EE3\u6570\u4E2D\uFF0C\u4E00\u4E2A\uFF08\u6709\u9650\u7EF4\uFF09\u5411\u91CF\u7A7A\u95F4\u603B\u53EF\u4EE5\u627E\u5230\u4E00\u7EC4\u57FA\uFF1A$\\\\{e_\\\\mu\\\\}$\uFF0C\u4F7F\u5F97\u4EFB\u610F\u4E00\u4E2A\u5411\u91CF\u90FD\u53EF\u4EE5\u5728\u8FD9\u7EC4\u57FA\u4E0B\u5C55\u5F00\u3002\\n\\n:::note[\u6307\u6807\u7EA6\u5B9A]\\n\\n\u5927\u5BB6\u53EF\u80FD\u66F4\u719F\u6089\u7528 $i,j,k$ \u4F5C\u4E3A\u6307\u6807\uFF0C\u6216\u8005\u663E\u793A\u5199\u51FA $1, 2, 3, \\\\dots$ \u3002\u5728\u5FAE\u5206\u51E0\u4F55\u91CC\u901A\u5E38\u4F7F\u7528\u5E0C\u814A\u5B57\u6BCD $\\\\mu,\\\\nu,\\\\rho,\\\\dots$ \u6765\u8868\u793A\u5411\u91CF\u53CA\u5176\u5206\u91CF\u7684\u6307\u6807\u3002\u8FD9\u53EA\u662F\u4E00\u79CD\u4E60\u60EF\u3002\\n\\n\u5728\u5E7F\u4E49\u76F8\u5BF9\u8BBA\u7684\u8BED\u5883\u4E0B\uFF08\u56DB\u7EF4\u65F6\u7A7A\uFF09\u901A\u5E38\u9ED8\u8BA4\uFF1A$\\\\mu,\\\\nu,\\\\rho,\\\\dots = 0,1,2,3$\uFF0C\u5176\u4E2D $0$ \u8868\u793A\u65F6\u95F4\u5206\u91CF\u3002\u4E0D\u8FC7\uFF0C\u51FA\u4E8E\u5F3A\u70C8\u7684\u5386\u53F2\u4E60\u60EF\u9057\u7559\uFF0C\u4E5F\u4F1A\u7528 $i,j,k,\\\\dots = 1,2,3$ \u8868\u793A\u7A7A\u95F4\u6307\u6807\u3002\\n\\n\u4E00\u822C\u7684\u7F57\u9A6C\u5B57\u6BCD\uFF08\u5982 $a,b,c$\uFF09\u4F1A\u88AB\u7528\u4F5C\u62BD\u8C61\u6307\u6807\uFF0C\u5B83\u4EEC\u4E0D\u53D6\u5177\u4F53\u6570\u503C\uFF0C\u53EA\u8868\u793A\u5F20\u91CF\u7C7B\u578B\uFF0C\u8FD9\u4E2A\u662F\u4E00\u4E2A\u6BD4\u8F83\u5FAE\u5999\u7684\u8BDD\u9898\uFF0C\u6211\u4EEC\u4E4B\u540E\u518D\u6765\u8BE6\u7EC6\u8BA8\u8BBA\u3002\\n\\n:::\\n\\n\u5728\u7ED9\u5B9A\u4E86\u4E00\u7EC4\u57FA\u4E4B\u540E\uFF0C\u4EFB\u610F\u5411\u91CF\u90FD\u53EF\u4EE5\u5C55\u5F00\u4E3A\uFF1A\\n\\n$$\\nv = \\\\sum_\\\\mu v^\\\\mu e_\\\\mu.\\n$$\\n\\n\u6CE8\u610F\uFF0C\u6211\u4EEC\u8FD9\u91CC\u5C06\u5411\u91CF\u7684\u5206\u91CF\u6807\u6CE8\u4E3A\u4E0A\u6807\uFF0C\u8FD9\u53EA\u662F\u5FAE\u5206\u51E0\u4F55\u91CC\u7684\u4E00\u79CD\u4E60\u60EF\u3002\u4F60\u4E4B\u540E\u4F1A\u53D1\u73B0\u8FD9\u79CD\u8BB0\u6CD5\u662F\u5F88\u6709\u9053\u7406\u7684\u3002\\n\\n### \u7231\u56E0\u65AF\u5766\u6C42\u548C\u7EA6\u5B9A\\n\\n\u4EE5\u4E0A\u90FD\u662F\u5F88\u57FA\u7840\u7684\u7EBF\u6027\u4EE3\u6570\u5185\u5BB9\u3002\u63A5\u4E0B\u6765\u6211\u4EEC\u8981\u5F00\u59CB\u4E3A\u5FAE\u5206\u51E0\u4F55\u505A\u94FA\u57AB\uFF1A\u5728\u5FAE\u5206\u51E0\u4F55\u4E2D\u6211\u4EEC\u5E38\u5E38\u4F1A\u9047\u5230\u5E26\u6709\u56DB\u4E2A\u6C42\u548C\u53F7\u7684\u8FD0\u7B97\uFF08\u6BD4\u5982\u9ECE\u66FC\u66F2\u7387\u5F20\u91CF\u5168\u7F29\u5E76\u5F97\u5230\u91CC\u5947\u6807\u91CF\uFF09\uFF0C\u8FD9\u4E2A\u65F6\u5019\u628A\u6240\u6709\u6C42\u548C\u53F7\u90FD\u5199\u51FA\u6765\u65E0\u7591\u4F1A\u8BA9\u4EBA\u5BF9\u4E8E\u6570\u5B66\u548C\u7269\u7406\u7684\u70ED\u60C5\u78E8\u706D\u3002\u4E3A\u6B64\uFF0C\u6211\u4EEC\u8981\u5F15\u5165**\u7231\u56E0\u65AF\u5766\u6C42\u548C\u7EA6\u5B9A**\uFF1A\\n\\n:::tip[\u7231\u56E0\u65AF\u5766\u6C42\u548C\u7EA6\u5B9A]\\n\\n\u5BF9\u4E8E\u5E26\u6709\u4EFB\u610F\u6307\u6807\u7684\u8BB0\u53F7\uFF0C\u4E0A\u4E0B\u6307\u6807\u51FA\u73B0\u91CD\u590D\u5B57\u6BCD\u65F6\uFF0C\u4EE3\u8868\u5BF9\u8FD9\u4E2A\u6307\u6807\u8FDB\u884C\u6C42\u548C\u3002\u6BD4\u5982\uFF1A\\n\\n$$\\nv^\\\\mu e_\\\\mu = \\\\sum_\\\\mu v^\\\\mu e_\\\\mu,\\n$$\\n\u6216\u8005\uFF1A\\n$$\\nA^\\\\mu{}_\\\\nu v^\\\\nu \\\\equiv \\\\sum_\\\\nu A^\\\\mu{}_\\\\nu v^\\\\nu.\\n$$\\n\\n\u6211\u4EEC\u6682\u65F6\u4E0D\u7528\u7BA1\u8FD9\u91CC\u9762\u7684\u8BB0\u53F7\u5177\u4F53\u662F\u4EC0\u4E48\u610F\u601D\uFF0C\u8BFB\u5230\u540E\u9762\u81EA\u7136\u4F1A\u6E05\u6670\u7684\u3002\u6211\u4EEC\u76EE\u524D\u53EF\u4EE5\u4EC5\u4EC5\u628A\u8FD9\u4E9B\u4E1C\u897F\u5F53\u6210\u4E00\u4E2A\u7B26\u53F7\u6E38\u620F\u3002\\n\\n:::\\n\\n:::note\\n\\n\u7269\u7406\u4EBA\u901A\u5E38\u4F1A\u7701\u7565\u57FA\uFF0C\u76F4\u63A5\u4F7F\u7528\u5206\u91CF $v^\\\\mu$ \u6765\u5B9A\u4E49\u4E00\u4E2A\u5411\u91CF\uFF0C\u7136\u540E\u7528\u5411\u91CF\u5206\u91CF\u7684\u53D8\u6362\u89C4\u5219\u6765\u52A0\u4EE5\u9650\u5236\u3002\u8FD9\u79CD\u5B9A\u4E49\u65B9\u5F0F\u53EF\u80FD\u66F4\u52A0\u76F4\u89C2\uFF0C\u4F46\u662F\u6709\u70B9\u201C\u6D6E\u4E8E\u8868\u8C61\u201D\u3002\u6211\u4EEC\u8FD9\u91CC\u7528\u6BD4\u8F83\u6570\u5B66\u7684\u5B9A\u4E49\uFF0C\u8FD9\u5BF9\u4E8E\u5BFB\u627E\u201C\u4E0D\u53D8\u91CF\u201D\uFF0C\u201C\u5178\u8303\u201D\u7684\u4E1C\u897F\u662F\u6709\u597D\u5904\u7684\u3002\u5177\u4F53\u800C\u8A00\uFF0C\u5728\u6211\u4EEC\u8FD9\u79CD\u5B9A\u4E49\u4E0B\uFF0C\u6211\u4EEC\u8981\u5F3A\u8C03\uFF1A\\n\\n1. $v^\\\\mu$ \u662F\u5411\u91CF $v$ \u5728\u57FA $\\\\{e_\\\\mu\\\\}$ \u4E0B\u7684\u5206\u91CF\uFF1B\\n2. $\\\\{e_\\\\mu\\\\}$ \u662F\u4E00\u7EC4\u771F\u5B9E\u7684\u5411\u91CF\u3002\\n\\n:::\\n\\n\\n## \u5BF9\u5076\u5411\u91CF\u7A7A\u95F4\\n\\n### \u5B9A\u4E49\\n\\n\u6211\u4EEC\u9996\u5148\u6765\u5B9A\u4E49\u5BF9\u5076\u5411\u91CF\u3002\\n\\n::::tip[\u5BF9\u5076\u5411\u91CF]\\n\\n\u4E00\u4E2A\u5BF9\u5076\u5411\u91CF\u662F\u5B9A\u4E49\u5728\u5411\u91CF\u7A7A\u95F4 $V$ \u4E0A\u7684\u7EBF\u6027\u6CDB\u51FD\uFF1A\\n\\n$$\\n\\\\omega: V \\\\to \\\\mathbb{R},\\n\\\\qquad\\nv \\\\mapsto \\\\omega(v).\\n$$\\n\\n\u5E76\u6EE1\u8DB3\u7EBF\u6027\u6761\u4EF6\uFF1A\\n\\n$$\\n\\\\omega(\\\\alpha v+\\\\beta w)\\n=\\n\\\\alpha \\\\omega(v)+\\\\beta \\\\omega(w),\\n\\\\qquad\\n\\\\forall v,w\\\\in V.\\n$$\\n\\n:::note\\n\u5982\u679C\u4F60\u66F4\u719F\u6089\u77E9\u9635\u8BED\u8A00\uFF0C\u53EF\u4EE5\u628A\u5B83\u60F3\u6210\u884C\u5411\u91CF\u3002\\n:::\\n\\n::::\\n\\n\u53EF\u4EE5\u81EA\u7136\u5730\u5B9A\u4E49\u5BF9\u5076\u5411\u91CF\u4E4B\u95F4\u7684\u52A0\u6CD5\u4E0E\u6570\u4E58\uFF0C\u4F7F\u5176\u771F\u6B63\u7684\u6210\u4E3A\u4E00\u4E2A\u5411\u91CF\uFF1A\\n\\n1. \u52A0\u6CD5\uFF1A$(\\\\omega_1 + \\\\omega_2)(v) = \\\\omega_1(v) + \\\\omega_2(v)$\uFF1B\\n2. \u6570\u4E58\uFF1A$(c \\\\cdot \\\\omega)(v) = c \\\\cdot \\\\omega(v) $\u3002\\n\\n\u53EF\u4EE5\u9A8C\u8BC1\u5728\u8FD9\u6837\u7684\u5B9A\u4E49\u4E0B\uFF0C\u6240\u6709\u5BF9\u5076\u5411\u91CF\u7EC4\u6210\u7684\u96C6\u5408\u6EE1\u8DB3\u5411\u91CF\u7A7A\u95F4\u7684\u5B9A\u4E49\uFF0C\u56E0\u6B64\u5B83\u4EEC\u7EC4\u6210\u4E86\u4E00\u4E2A\u65B0\u7684\u5411\u91CF\u7A7A\u95F4\uFF0C\u8BB0\u4E3A $ V^* $\u3002\\n\\n### \u5BF9\u5076\u57FA\\n\\n\u65E2\u7136\u5BF9\u5076\u5411\u91CF\u4E5F\u6784\u6210\u4E00\u4E2A\u5411\u91CF\u7A7A\u95F4\uFF0C\u6211\u4EEC\u81EA\u7136\u5730\u4F1A\u8003\u8651\u8FD9\u4E2A\u7A7A\u95F4\u7684\u57FA\u662F\u4EC0\u4E48\u3002\u6CE8\u610F\uFF1A\u82E5 $V$ \u7684\u4E00\u7EC4\u57FA\u4E3A $\\\\{e_\\\\mu\\\\}$\uFF0C\u6211\u4EEC\u53EF\u4EE5\u5B9A\u4E49**\u5BF9\u5076\u57FA**\uFF1A\\n\\n::::tip[\u5BF9\u5076\u57FA]\\n\\n\u7ED9\u5B9A $V$ \u7684\u4E00\u7EC4\u57FA\u4E3A $\\\\{e_\\\\mu\\\\}$\uFF0C\u5B9A\u4E49 $\\\\{e^\\\\mu\\\\}$ \u4E3A $V^*$ \u4E2D\u7684\u4E00\u7EC4\u5411\u91CF\uFF0C\u6EE1\u8DB3\uFF1A\\n\\n$$\\ne^\\\\mu(e_\\\\nu)=\\\\delta^\\\\mu{}_\\\\nu.\\n$$\\n\\n:::note\\n\u8FD9\u91CC $\\\\delta^\\\\mu{}_\\\\nu$ \u5176\u5B9E\u5C31\u662F\u5927\u540D\u9F0E\u9F0E\u7684 Kronecker delta\uFF1A\\n\\n$$\\n\\\\delta^\\\\mu{}_\\\\nu=\\n\\\\begin{cases}\\n1, & \\\\mu=\\\\nu,\\\\\\\\\\n0, & \\\\mu\\\\neq\\\\nu.\\n\\\\end{cases}\\n$$\\n\\n\u5FAE\u5206\u51E0\u4F55\u4E60\u60EF\u4E8E\u628A\u5B83\u8BB0\u505A\u4E00\u4E0A\u4E00\u4E0B\u4E24\u4E2A\u6307\u6807\uFF0C\u4ECE\u800C\u53EF\u4EE5\u7528\u5B83\u6765\u4EE3\u8868\u5355\u4F4D\u77E9\u9635\u3002\\n\\nKronecker delta \u6709\u4E00\u4E2A\u57FA\u672C\u6027\u8D28\uFF1A\\n\\n$$\\n\\\\delta^\\\\mu{}_\\\\nu v^\\\\nu = v^\\\\mu.\\n$$\\n\\n\u4E5F\u5373\u66FF\u6362\u6307\u6807\u3002\\n\\n:::\\n\\n:::note\\n\\n\u4E8B\u5B9E\u4E0A\uFF0C\u9700\u8981\u9A8C\u8BC1 $\\\\{e^\\\\mu\\\\}$ \u7684\u786E\u662F\u4E00\u7EC4\u57FA\uFF0C\u4E5F\u5373\u5BF9\u4E8E\u4EFB\u610F $V^*$ \u7684\u5143\u7D20 $\\\\omega$\uFF0C\u90FD\u53EF\u4EE5\u5C55\u5F00\u4E3A $\\\\{e^\\\\mu\\\\}$ \u7684\u7EBF\u6027\u7EC4\u5408\uFF0C\u4E5F\u5373\uFF1A\\n\\n$$\\n\\\\omega = \\\\omega_\\\\mu e^\\\\mu.\\n$$\\n\\n\u6211\u4EEC\u8FD9\u91CC\u4ECD\u7136\u662F\u7528\u4E86\u7231\u56E0\u65AF\u5766\u6C42\u548C\u7EA6\u5B9A\u3002\u53EF\u4EE5\u770B\u5230\uFF1A\u5411\u91CF\u5206\u91CF\u7528\u4E0A\u6807\u6807\u8BB0\uFF0C\u800C\u5BF9\u5076\u5411\u91CF\u5206\u91CF\u7528\u4E0B\u6807\u3002\u8FD9\u4E2A\u7EA6\u5B9A\u4E0D\u662F\u88C5\u9970\uFF0C\u5B83\u5BF9\u5E94\u4E0D\u540C\u7684\u53D8\u6362\u89C4\u5F8B\uFF0C\u540E\u9762\u4F1A\u770B\u5230\u539F\u56E0\u3002\\n\\n:::\\n::::\\n\\n\u663E\u7136\uFF0C\u5728\u8FD9\u6837\u7684\u5B9A\u4E49\u4E0B\uFF0C\u6211\u4EEC\u53EF\u4EE5\u6CE8\u610F\u5230\u4E00\u4E2A\u91CD\u8981\u7684\u4E8B\u5B9E\uFF1A\uFF08\u5BF9\u4E8E\u6709\u9650\u7EF4\u5411\u91CF\u7A7A\u95F4\uFF09 $\\\\dim V = \\\\dim V^* $\u3002\\n\\n:::note\\n\\n\u5F88\u591A\u7EBF\u6027\u4EE3\u6570\u6559\u6750\u4F1A\u628A\u5BF9\u5076\u57FA\u5199\u6210 $e_\\\\mu^* $\uFF0C\u4F46\u5FAE\u5206\u51E0\u4F55\u91CC\u901A\u5E38\u76F4\u63A5\u5199$e^\\\\mu$\uFF0C\u8FD9\u6837\u540E\u9762\u5904\u7406\u5F20\u91CF\u65F6\u4F1A\u66F4\u81EA\u7136\u3002\\n\\n:::\\n\\n## \u5BF9\u5076\u7684\u5BF9\u5076\uFF1A\u81EA\u7136\u540C\u6784\\n\\n\u65E2\u7136 $V^*$ \u662F\u5411\u91CF\u7A7A\u95F4\uFF0C\u6211\u4EEC\u8FD8\u80FD\u7EE7\u7EED\u5B9A\u4E49 $V^{**}$\uFF0C\u4E5F\u5373\u5BF9\u5076\u7A7A\u95F4\u7684\u5BF9\u5076\u7A7A\u95F4\u3002\u4F46\u662F\u6CE8\u610F\uFF1A$V^{**}$ \u540C\u6837\u662F\u5411\u91CF\u7A7A\u95F4\uFF0C\u6211\u4EEC\u53EF\u4EE5\u65E0\u9650\u91CD\u590D\u5957\u5A03\uFF0C\u8FD9\u5C31\u4F1A\u5F15\u53D1\u6211\u4EEC\u7684\u6000\u7591\uFF1A\u5BF9\u5076\u7684\u5BF9\u5076\u771F\u7684\u662F\u5FC5\u8981\u7684\u5417\uFF1F\u4E8B\u5B9E\u4E0A\uFF0C\u6211\u4EEC\u6709\u4E00\u79CD\u5DE7\u5999\u7684\u65B9\u5F0F\u628A $V^{**}$ \u4E0E $V$ \u81EA\u7136\u8054\u7CFB\u8D77\u6765\uFF1A\\n\\n:::tip[$V^{**}$ \u4E0E $V$ \u7684\u81EA\u7136\u540C\u6784]\\n\\n\u6CE8\u610F\u5BF9\u4E8E\u4EFB\u610F $v \\\\in V$\uFF0C\u6211\u4EEC\u90FD\u53EF\u4EE5\u5B9A\u4E49\u4E00\u4E2A $V^*$ \u4E0A\u7684\u7EBF\u6027\u6CDB\u51FD $v\'$:\\n\\n$$\\nv\'(\\\\omega)=\\\\omega(v),\\n$$\\n\\n\u7136\u800C\u5B9A\u4E49\u5728 $V^*$ \u4E0A\u7684\u7EBF\u6027\u6CDB\u51FD\uFF0C\u6070\u597D\u5C31\u662F $V^{**}$ \u4E2D\u7684\u4E00\u4E2A\u5143\u7D20\u3002\u4E5F\u5C31\u662F\u8BF4\uFF1A\u6BCF\u4E2A $V$ \u4E2D\u7684\u5411\u91CF\u90FD\u81EA\u7136\u5BF9\u5E94\u4E00\u4E2A $V^{**}$ \u4E2D\u7684\u5143\u7D20\u3002\u6362\u53E5\u8BDD\u8BF4\uFF1A\\n\\n$$\\nV \\\\cong V^{**}.\\n$$\\n\\n\u6CE8\u610F\u8FD9\u4E2A\u540C\u6784\u5173\u7CFB\u4E0D\u4F9D\u8D56\u4E8E\u57FA\u7684\u9009\u53D6\uFF0C\u6211\u4EEC\u79F0\u4E4B\u4E3A**\u81EA\u7136\u540C\u6784**\uFF0C\u6216\u8005**\u5178\u8303\u540C\u6784**\u3002\\n\\n:::\\n\\n\u8FD9\u4E2A\u6027\u8D28\u5141\u8BB8\u6211\u4EEC\u628A\u5411\u91CF\u548C\u5BF9\u5076\u5411\u91CF\u81EA\u7136\u914D\u5BF9\uFF1A\\n\\n$$\\n\\\\omega(v)=\\\\omega_\\\\mu v^\\\\mu.\\n$$\\n\\n\u540C\u7406\uFF1A\\n\\n$$\\nv(\\\\omega)=v^\\\\mu\\\\omega_\\\\mu.\\n$$\\n\\n\u56E0\u6B64\uFF1A\\n\\n$$\\n\\\\omega_\\\\mu v^\\\\mu=v^\\\\mu\\\\omega_\\\\mu.\\n$$\\n\\n\u8FD9\u770B\u8D77\u6765\u5F88\u5E73\u51E1\uFF0C\u4F46\u5B83\u8BF4\u660E\u4E00\u4E2A\u5F88\u91CD\u8981\u7684\u4E8B\u5B9E\uFF1A\u53EA\u8981\u6307\u6807\u7ED3\u6784\u6B63\u786E\uFF0C\u6211\u4EEC\u5C31\u53EF\u4EE5\u628A\u5206\u91CF\u5F53\u4F5C\u666E\u901A\u6807\u91CF\u5904\u7406\uFF0C\u800C\u4E0D\u7528\u53BB\u601D\u8003\u6620\u5C04\u4E0E\u6620\u5C04\u7684\u590D\u5408\u3002\u8FD9\u5C31\u662F\u7231\u56E0\u65AF\u5766\u6C42\u548C\u7EA6\u5B9A\u7684\u5F3A\u5927\u4E4B\u5904\u3002\\n\\n:::note\\n\\n\u5982\u679C\u4F60\u4E0D\u6E05\u695A\u4E0A\u9762\u8FD9\u4E9B\u7B49\u5F0F\u90FD\u662F\u600E\u4E48\u6765\u7684\uFF0C\u53EF\u4EE5\u663E\u5F0F\u5730\u628A\u57FA\u5199\u51FA\u6765\uFF0C\u7136\u540E\u8003\u8651\u57FA\u4E0E\u5BF9\u5076\u57FA\u4E4B\u95F4\u7684\u76F8\u4E92\u4F5C\u7528\u3002\u6CE8\u610F\u5229\u7528\u5206\u91CF\u662F\u666E\u901A\u5B9E\u6570\uFF08\u6807\u91CF\uFF09\u7684\u4E8B\u5B9E\uFF0C\u8003\u8651\u5BF9\u5076\u5411\u91CF\u662F\u7EBF\u6027\u7684\u6CDB\u51FD\u3002\\n\\n:::\\n\\n:::warning\\n\\n\u6CE8\u610F\u4E0A\u9762\u7684\u8BA8\u8BBA\u90FD\u9ED8\u8BA4\u6709\u9650\u7EF4\u7A7A\u95F4\uFF0C\u5BF9\u4E8E\u65E0\u9650\u7EF4\u7A7A\u95F4 $V^*$ \u5F80\u5F80\u6BD4 $V$ \u66F4\u5927\uFF0C$V^{**}$ \u4E5F\u901A\u5E38\u6BD4 $V$ \u66F4\u5927\u3002\u56E0\u6B64\u901A\u5E38\u800C\u8A00\uFF1A\\n\\n$$\\nV \\\\not\\\\cong V^{**}\\n$$\\n\\n\u8FD9\u4E5F\u662F\u4E3A\u4EC0\u4E48\u91CF\u5B50\u529B\u5B66\u540C\u6837\u6D89\u53CA\u5411\u91CF\uFF08\u5DE6\u77E2\uFF09\u4E0E\u5BF9\u5076\u5411\u91CF\uFF08\u53F3\u77E2\uFF09\uFF0C\u8FD8\u6709\u5F20\u91CF\uFF08\u7B97\u5B50\uFF09\uFF0C\u5374\u901A\u5E38\u4E0D\u4F1A\u76F4\u63A5\u4F7F\u7528\u7231\u56E0\u65AF\u5766\u6C42\u548C\u7EA6\u5B9A\u7684\u539F\u56E0\u3002\u5C24\u5176\u662F\uFF0C\u6211\u4EEC\u9700\u8981\u7279\u522B\u8C28\u614E\u5730\u5BF9\u5F85 $|x\\\\rangle, |p\\\\rangle$ \u8FD9\u4E24\u4E2A\u5411\u91CF\u3002\\n\\n\u611F\u5174\u8DA3\u7684\u8BDD\u53EF\u4EE5\u7EE7\u7EED\u4E86\u89E3*\u88C5\u5907\u5E0C\u5C14\u4F2F\u7279\u7A7A\u95F4*\u3002\\n\\n:::"},{"id":"/Differential Geometry and Fibre Bundle/1_1","metadata":{"permalink":"/zh/blog/Differential Geometry and Fibre Bundle/1_1","source":"@site/i18n/zh/docusaurus-plugin-content-blog/Differential Geometry and Fibre Bundle/1_1.mdx","title":"\u62D3\u6251\u57FA\u7840","description":"\u6211\u4EEC\u8FD9\u91CC\u9ED8\u8BA4\u5927\u5BB6\u719F\u6089\u96C6\u5408\u7684\u4E00\u4E9B\u57FA\u7840\u5B9A\u4E49\u548C\u6982\u5FF5\u3002\u5BF9\u4E8E\u7269\u7406\u7528\u5FAE\u5206\u51E0\u4F55\u800C\u8A00\uFF0C\u6211\u4EEC\u5E76\u4E0D\u9700\u8981\u592A\u591A\u62D3\u6251\u7684\u77E5\u8BC6\u3002\u5982\u679C\u5728\u9605\u8BFB\u7684\u65F6\u5019\u9047\u5230\u56F0\u96BE\u53EF\u4EE5\u5148\u8DF3\u8FC7\uFF0C\u5B83\u51E0\u4E4E\u4E0D\u4F1A\u5F71\u54CD\u540E\u9762\u7684\u7406\u89E3\u3002","date":"2026-05-15T00:00:00.000Z","tags":[{"inline":true,"label":"Differential Geometry","permalink":"/zh/blog/tags/differential-geometry"},{"inline":true,"label":"Topology","permalink":"/zh/blog/tags/topology"}],"readingTime":4.83,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"\u62D3\u6251\u57FA\u7840","date":"2026-05-15T00:00:00.000Z","tags":["Differential Geometry","Topology"]},"unlisted":false,"prevItem":{"title":"\u5FAE\u5206\u51E0\u4F55\u7684\u7EBF\u6027\u4EE3\u6570\u57FA\u7840","permalink":"/zh/blog/Differential Geometry and Fibre Bundle/1_2"}},"content":"> \u6211\u4EEC\u8FD9\u91CC\u9ED8\u8BA4\u5927\u5BB6\u719F\u6089\u96C6\u5408\u7684\u4E00\u4E9B\u57FA\u7840\u5B9A\u4E49\u548C\u6982\u5FF5\u3002\u5BF9\u4E8E\u7269\u7406\u7528\u5FAE\u5206\u51E0\u4F55\u800C\u8A00\uFF0C\u6211\u4EEC\u5E76\u4E0D\u9700\u8981\u592A\u591A\u62D3\u6251\u7684\u77E5\u8BC6\u3002\u5982\u679C\u5728\u9605\u8BFB\u7684\u65F6\u5019\u9047\u5230\u56F0\u96BE\u53EF\u4EE5\u5148\u8DF3\u8FC7\uFF0C\u5B83\u51E0\u4E4E\u4E0D\u4F1A\u5F71\u54CD\u540E\u9762\u7684\u7406\u89E3\u3002\\n\\n## \u5B9A\u4E49\uFF1A\u62D3\u6251\\n\\n\u6570\u5B66\u5BB6\u63D0\u5230\u7684\u62D3\u6251\u548C\u7269\u7406\u5B66\u5BB6\u63D0\u5230\u7684\u6709\u4E00\u4E9B\u5FAE\u5999\u7684\u4E0D\u540C\u3002\u6211\u4EEC\u8FD9\u91CCfollow\u6570\u5B66\u5BB6\u4E25\u8C28\u7684\u5B9A\u4E49\uFF1A\\n\\n:::tip[\u62D3\u6251]\\n\\n\u7ED9\u5B9A\u4E00\u4E2A\u96C6\u5408 $X$\uFF0C\u6211\u4EEC\u6784\u5EFA\u53E6\u4E00\u4E2A\u96C6\u5408 $\\\\mathscr{T}$\uFF0C\u5176\u4E2D\u5305\u542B$X$\u7684\u6240\u6709\u201C\u5F00\u5B50\u96C6\u201D\uFF0C\u8FD9\u4E2A\u96C6\u5408 $\\\\mathscr{T}$ \u5C31\u88AB\u79F0\u4E3A$X$\u7684\u62D3\u6251\u3002 \\n\\n:::\\n\\n:::info[\u62D3\u6251\u9700\u8981\u6EE1\u8DB3\u7684\u6761\u4EF6]\\n\\n\u4E3A\u4E86\u4F7F\u5F97\u6211\u4EEC\u5BF9\u62D3\u6251\u548C\u5F00\u96C6\u7684\u5B9A\u4E49\u662F\u81EA\u6D3D\u7684\uFF0C$\\\\mathscr{T}$\u9700\u8981\u6EE1\u8DB3\u5982\u4E0B\u7684\u4E09\u4E2A\u6761\u4EF6\uFF1A\\n \\n1. $X, \\\\varnothing \\\\in \\\\mathscr{T}$;\\n2. \u82E5 $\\\\ O_i \\\\in \\\\mathscr{T},  i = 1,  2,  \\\\dots,  n$\uFF0C\u5219 $\\\\bigcap\\\\limits_{i=1}^n O_i \\\\in \\\\mathscr{T}$;\\n3. \u82E5 $\\\\ O_i \\\\in \\\\mathscr{T},  \\\\forall i$\uFF0C\u5219 $\\\\bigcup\\\\limits_{i} O_i \\\\in \\\\mathscr{T}$. \\n\\n:::\\n\\n:::note[\u5907\u6CE8]\\n\\n\u8FD9\u91CC\u8981\u6CE8\u610F\uFF1A\u7B2C\u4E8C\u6761\u8981\u6C42\u6709\u9650\u591A\u4E2A\u5F00\u96C6\u7684\u4EA4\u96C6\u624D\u80FD\u4FDD\u6301\u5F00\u96C6\uFF1B\u800C\u7B2C\u4E09\u6761\u5E76\u6CA1\u6709\u5BF9\u5E76\u96C6\u7684\u6570\u91CF\u63D0\u51FA\u8981\u6C42\uFF0C\u5373\u65E0\u9650\u591A\u4E2A\u5F00\u96C6\u7684\u5E76\u96C6\u4ECD\u7136\u4FDD\u6301\u5F00\u3002\u4E3E\u4E2A\u4F8B\u5B50, \u8003\u8651: $U_n = \\\\{x | \\\\left|x\\\\right| < 1+ \\\\frac{1}{n} \\\\}$, \u5219 $\\\\bigcap\\\\limits_{i=1}^\\\\infty U_n \\\\to [-1,  1]$\u3002\u8FD9\u4E0D\u662F $\\\\mathbb{R}$ \u7684\u4E00\u4E2A\u5F00\u5B50\u96C6!\\n\\n:::\\n\\n## \u4E3E\u4F8B\uFF1A\u4E0D\u540C\u79CD\u7C7B\u7684\u62D3\u6251\\n\\n\u8FD9\u91CC\u6211\u4EEC\u4E3E\u4E09\u4E2A\u7279\u6B8A\u7684\u4F8B\u5B50\u3002\u4E8B\u5B9E\u4E0A\u7ED9\u5B9A\u4E00\u4E2A\u96C6\u5408 $X$\uFF0C\u901A\u5E38\u6709\u65E0\u7A77\u591A\u79CD\u9009\u53D6\u62D3\u6251\u7684\u65B9\u6CD5\u3002\\n\\n:::info[\u901A\u5E38\u62D3\u6251]\\n\\n\u8BBE$X = \\\\mathbb{R}^n$, \u5219\u5176**\u901A\u5E38\u62D3\u6251\u4E3A** $\\\\mathscr{T}_u = \\\\{\\\\varnothing, \\\\bigcup_{x_0, r} B(x_0, r)\\\\}$\u3002\u8FD9\u91CC $B(x_0, r) = \\\\{x \\\\in \\\\mathbb{R}^n| \\\\left|x-x_0\\\\right| < r\\\\}$\uFF0C\u5176\u4E2D $x_0 \\\\in \\\\mathbb{R}^n, r>0 \\\\in \\\\mathbb{R}$ \u88AB\u79F0\u4F5C\u5F00\u7403\u3002 \\n\\n\u8FD9\u91CC $\\\\mathbb{R}^n$ \u4E2D\u7684\u8DDD\u79BB\u6309\u7167\u901A\u5E38\u7684\u65B9\u5F0F\u5B9A\u4E49: $\\\\left|x-x_0\\\\right| = \\\\sqrt{\\\\sum_{\\\\mu=1}^n(x^\\\\mu-x_0^\\\\mu)^2}$. \u6CE8\u610F\uFF1A\u8FD9\u91CC $x^\\\\mu$ \u4EE3\u8868 $x$ \u7684\u7B2C $\\\\mu$ \u5206\u91CF\uFF0C\u800C\u4E0D\u662F\u5E42\u6307\u6570\u3002\u8FD9\u662F\u5FAE\u5206\u51E0\u4F55\u7684\u60EF\u7528\u7EA6\u5B9A\u3002\\n\\n\u4E8B\u5B9E\u4E0A\uFF0C\u8FD9\u53EA\u662F $\\\\mathbb{R}$ \u4E0A\u5F00\u533A\u95F4\u7684\u76F4\u63A5\u63A8\u5E7F\u3002\\n:::\\n\\n:::info[\u79BB\u6563\u62D3\u6251]\\n\\n\u5BF9\u4E8E\u4EFB\u610F\u4E00\u4E2A\u96C6\u5408 $X$, \u6211\u4EEC\u5B9A\u4E49\u5176\u62D3\u6251 $\\\\mathscr{T}$ \u4E3A $X$ \u7684\u5168\u90E8\u5B50\u96C6\u3002\u8FD9\u662F\u4E00\u4E2A\u6709\u70B9\u65E0\u804A\u7684\u5B9A\u4E49\u3002\\n\\n:::\\n\\n:::info[\u51DD\u805A\u62D3\u6251]\\n\\n\u5BF9\u4E8E\u4EFB\u610F\u4E00\u4E2A\u96C6\u5408 $X$, \u5B9A\u4E49\uFF1A $\\\\mathscr{T} = \\\\{\\\\varnothing, X\\\\}$\u3002\u8FD9\u540C\u6837\u662F\u4E00\u4E2A\u65E0\u804A\u7684\u5B9A\u4E49\u3002\\n\\n:::\\n\\n## \u5B9A\u4E49\uFF1A\u8FDE\u7EED\u6027\\n\\n\u5BF9\u4E8E\u4E00\u4E2A\u901A\u5E38\u610F\u4E49\u4E0A\u7684\u4E00\u5143\u51FD\u6570 $f(x)$\uFF0C\u6211\u4EEC\u662F\u7528 $\\\\varepsilon-\\\\delta$ \u8BED\u8A00\u5B9A\u4E49\u5B83\u7684\u8FDE\u7EED\u6027\u7684\uFF1A\\n\\n:::note[\u8FDE\u7EED\u6027]\\n\\n\u82E5 $\\\\forall \\\\varepsilon > 0$, $\\\\exists \\\\delta >0$, \u4F7F\u5F97\u5F53 $\\\\left|f(x) - f(x_0)\\\\right| < \\\\varepsilon $ \u65F6, \u6709 $\\\\left|x-x_0\\\\right| < \\\\delta$. \\n\\n:::\\n\\n\u4F46\u662F\u6211\u4EEC\u73B0\u5728\u53EA\u6709\u4E00\u4E2A\u62D3\u6251\u7A7A\u95F4, \u8FD9\u4E0A\u9762\u5927\u6982\u7387\u6CA1\u6709\u826F\u597D\u5B9A\u4E49\u7684\u52A0\u51CF\u6CD5, \u66F4\u6CA1\u6709\u529E\u6CD5\u5B9A\u4E49\u4E00\u4E2A\u201C\u987A\u5E8F\u201D, \u4E5F\u5C31\u6CA1\u6709\u529E\u6CD5\u6BD4\u8F83\u5927\u5C0F\u3002\u540C\u65F6\u6211\u4EEC\u4E5F\u6CA1\u6709\u4E00\u4E2A\u201C\u5EA6\u91CF\u201D\u6765\u8861\u91CF\u4E24\u4E2A\u5143\u7D20\u95F4\u7684\u201C\u8DDD\u79BB\u201D\u3002\u56E0\u6B64\u6211\u4EEC\u8F6C\u800C\u5BFB\u627E\u529E\u6CD5\u62D3\u5C55\u8FDE\u7EED\u6027\u7684\u5B9A\u4E49\u3002\u5BF9\u4E8E\u62D3\u6251\u7A7A\u95F4\uFF0C\u6211\u4EEC\u53EA\u6709\u529E\u6CD5\u8861\u91CF\u5F00\u96C6\uFF0C\u56E0\u6B64\u6211\u4EEC\u9700\u8981\u7528\u96C6\u5408\u7684\u8BED\u8A00\u6765\u91CD\u65B0\u8868\u8FF0$\\\\varepsilon-\\\\delta$\u8BED\u8A00\uFF1A\\n\\n:::tip[\u8FDE\u7EED\u6027\uFF1A\u96C6\u5408\u8BED\u8A00]\\n\\n\u82E5\u6620\u5C04 $f$ \u7684\u50CF $f[X]$ \u7684\u4EFB\u610F\u5F00\u5B50\u96C6 $U$, \u5176\u539F\u50CF $f^{-1}[U]$ \u90FD\u662F\u5F00\u5B50\u96C6, \u5219 $f$ \u8FDE\u7EED. \\n\\n:::\\n\\n\u4E4D\u4E00\u770B\u8FD9\u4E2A\u5B9A\u4E49\u597D\u50CF\u6CA1\u6709\u4EFB\u4F55\u9053\u7406, \u4F46\u662F\u6211\u4EEC\u7684\u786E\u53EF\u4EE5\u8BC1\u660E\u5B83\u662F\u4E0E $\\\\varepsilon-\\\\delta$ \u8BED\u8A00\u5728 $\\\\mathbb{R}$ \u4E0A\u662F\u7B49\u4EF7\u7684\uFF08\u4E8B\u5B9E\u4E0A, \u5BF9\u4E8E\u4EFB\u4F55\u4E00\u4E2A\u914D\u5907\u4E86\u5EA6\u91CF\u7684\u62D3\u6251\u7A7A\u95F4\u90FD\u662F\u6210\u7ACB\u7684\uFF09\u3002\u6211\u4EEC\u8FD9\u91CC\u7565\u53BB\u5BF9\u8FD9\u4E2A\u7B49\u4EF7\u6027\u7684\u8BC1\u660E\uFF0C\u56E0\u4E3A\u4F5C\u4E3A\u7269\u7406\u4EBA\uFF0C\u6211\u4EEC\u6CA1\u6709\u5FC5\u8981\u5173\u6CE8\u592A\u591A\u7684\u7EC6\u8282\u3002\u4E0D\u8FC7\u8FD9\u4E2A\u8BC1\u660E\u662F\u5F88\u7B80\u5355\u7684\uFF0C\u5C1D\u8BD5\u5229\u7528\u5F00\u7403\u7684\u5B9A\u4E49\u5373\u53EF\u3002\\n\\n\u5BF9\u4E8E\u4E00\u822C\u7684\u51FD\u6570, \u6211\u4EEC\u7528 $C^r$ \u6765\u6307\u4EE3\u5B83\u4E00\u76F4\u5230 $r$ \u9636\u5BFC\u51FD\u6570\u5B58\u5728\u4E14\u8FDE\u7EED, \u7279\u522B\u5730, $C^0$ \u6307\u8FDE\u7EED\u51FD\u6570\u3001$C^\\\\infty$ \u6307\u5149\u6ED1\u51FD\u6570. \u6211\u4EEC\u5C06\u5BF9\u4E8E\u66F4\u4E00\u822C\u5730\u6620\u5C04\u6CBF\u7528\u8FD9\u4E2A\u79F0\u547C\u3002\u6CE8\u610F\uFF1A\u5BF9\u4E8E\u53EA\u5305\u542B\u4E86\u62D3\u6251\u7ED3\u6784\u7684\u96C6\u5408\u800C\u8A00, \u5B9A\u4E49\u5728\u5176\u4E0A\u7684\u6620\u5C04\u7684\u6700\u9AD8\u8981\u6C42\u5C31\u662F $C^0$\u3002\\n\\n## \u5B9A\u4E49\uFF1A\u540C\u80DA\\n\\n\u540C\u80DA\u662F\u4E00\u4E2A\u7528\u6765\u8861\u91CF\u4E24\u4E2A\u62D3\u6251\u7A7A\u95F4\u201C\u6709\u591A\u76F8\u4F3C\u201D\u7684\u6620\u5C04\u3002\u5177\u4F53\u800C\u8A00\uFF0C\u6211\u4EEC\u5B9A\u4E49\uFF1A\\n\\n:::tip[\u540C\u80DA]\\n\\n\u5982\u679C\u4E24\u4E2A\u62D3\u6251\u7A7A\u95F4 $(X,  \\\\mathscr{T})$\uFF0C $(Y,  \\\\mathscr{S})$ \u4E4B\u95F4\u5B58\u5728\u4E00\u4E2A\u6620\u5C04$f$\uFF0C\u6EE1\u8DB3\u4EE5\u4E0B\u6761\u4EF6\uFF1A\\n\\n1. $f$ \u4E3A\u53CC\u5C04\uFF1B\\n2. $f,  f^{-1}$ \u7686\u4E3A\u8FDE\u7EED\u6620\u5C04\uFF0C\\n\\n\u5219\u79F0\u8FD9\u4E24\u4E2A\u62D3\u6251\u7A7A\u95F4\u4E92\u76F8**\u540C\u80DA**\uFF0C$f$\u662F\u4E00\u4E2A\u540C\u80DA\u6620\u5C04\u3002 \\n\\n:::\\n\\n:::note[\u5907\u6CE8]\\n\\n\u4E00\u822C\u800C\u8A00, \u5982\u679C $f$ \u4E3A\u8FDE\u7EED\u6620\u5C04, \u5176\u9006\u4E5F\u5B58\u5728, \u5219\u5176\u9006\u6620\u5C04\u4E5F\u8FDE\u7EED\u3002\u7136\u800C\uFF0C\u4F60\u53EF\u4EE5\u7528\u524D\u9762\u63D0\u5230\u7684\u79BB\u6563\u62D3\u6251\u548C\u51DD\u805A\u62D3\u6251\u5F3A\u884C\u5B9A\u4E49\u4E00\u4E2A\u53CD\u4F8B\u51FA\u6765\uFF1A\\n\\n\u4EE4$(X,  \\\\mathscr{T})$ \u7684\u62D3\u6251\u4E3A\u79BB\u6563\u62D3\u6251\uFF08\u6240\u6709\u7684\u5B50\u96C6\u90FD\u662F\u5F00\u5B50\u96C6\uFF09\uFF0C$(Y,  \\\\mathscr{S})$ \u7684\u62D3\u6251\u4E3A\u51DD\u805A\u62D3\u6251\uFF08\u53EA\u6709$Y$\u548C$\\\\varnothing$\u662F\u5F00\u5B50\u96C6\uFF09\uFF0C\u5219\u5BF9\u4E8E\u4EFB\u610F\u53CC\u5C04 $f$ \u90FD\u662F\u8FDE\u7EED\u7684\uFF1A\u53EA\u6709 $Y=f[X]$ \u4E3A\u5F00\u5B50\u96C6, \u800C\u5176\u539F\u50CF $f^{-1}[Y]=X$ \u4E5F\u662F\u5F00\u96C6\uFF1B\u4F46\u5BF9\u4E8E\u4EFB\u610F\u9006\u6620\u5C04 $f^{-1}$ \u90FD\u4E0D\u662F\u8FDE\u7EED\u7684\uFF1A\u4EFB\u610F\u5B50\u96C6 $U \\\\subseteq X$ \u90FD\u662F\u5F00\u5B50\u96C6\uFF0C\u7136\u800C\u5176\u539F\u50CF $f^{-1}[U]$ \u90FD\u4E0D\u662F\u5F00\u5B50\u96C6\uFF0C\u9664\u975E$U=X$\u3002\\n\\n\u8FD9\u662F\u79BB\u6563\u62D3\u6251\u548C\u51DD\u805A\u62D3\u6251\u51E0\u4E4E\u552F\u4E00\u7684\u5E94\u7528\uFF0C\u548C\u5B83\u4EEC\u7684\u5B9A\u4E49\u4E00\u6837\u65E0\u804A\u3002\\n\\n:::"}]}}')}}]);